<script setup>
import {computed,onMounted,ref} from 'vue'
import {withBase} from 'vitepress'
import allSections from '../../../data/classes.json'
const props=defineProps({section:{type:String,default:''}})
const data=computed(()=>allSections[props.section]||Object.values(allSections)[0])
const selected=ref(data.value?.classes[0]?.date||'')
const card=computed(()=>data.value.classes.find(c=>c.date===selected.value)||data.value.classes[0])
const link=path=>{if(/^https?:/.test(path))return path;const [route,hash]=path.split('#');return withBase(route+(route.endsWith('/')||/\.[a-z]+$/i.test(route)?'':'.html')+(hash?'#'+hash:''))}
const checkpoint=key=>data.value.checkpoints.find(c=>c.key===key)
const dueText=key=>{const c=checkpoint(key);const [y,m,d]=c.date.split('-');return `${c.title} — ${Number(m)}/${Number(d)}/${y}, ${c.time} Eastern`}
onMounted(()=>{const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());selected.value=(data.value.classes.find(c=>c.date>=today)||data.value.classes.at(-1)).date})
</script>
<template><section class="class-work-card" aria-label="Class preparation and submission card"><label :for="'class-date-'+section">Choose your class date</label><select :id="'class-date-'+section" v-model="selected"><option v-for="c in data.classes" :key="c.date" :value="c.date">{{c.label}}</option></select><h3>{{card.label}}</h3><dl><dt>Bring</dt><dd>{{card.bring}}</dd><dt>In class</dt><dd>{{card.work}}</dd><dt>Peer review</dt><dd>{{card.review}}</dd><dt>Update</dt><dd>{{card.update}}</dd></dl><div v-for="kind in ['due','next']" :key="kind"><template v-if="card[kind]?.length"><strong>{{kind==='due'?'Due / target':'Next submission / target'}}</strong><ul><li v-for="key in card[kind]" :key="key"><span class="status">{{checkpoint(key).status==='posted'?'Posted':'Planned'}}</span> {{dueText(key)}}<template v-if="checkpoint(key).assignmentId"> · <a :href="'https://njit.instructure.com/courses/'+data.courseId+'/assignments/'+checkpoint(key).assignmentId">Open assignment</a></template></li></ul></template></div><p v-if="card.note" class="class-work-note">{{card.note}}</p><p><a :href="link(card.guide.link)">{{card.guide.text}}</a> · <a :href="link(card.example.link)">{{card.example.text}}</a> · <a :href="'https://njit.instructure.com/courses/'+data.courseId+'/assignments'">Canvas assignments</a></p><small>Posted = an existing Canvas assignment. Planned = roadmap target until Canvas posts it. Use Canvas for graded deadlines and submissions. Keep the same project record.</small></section></template>
<style scoped>.class-work-card{padding:22px;border:2px solid var(--vp-c-brand-1);border-radius:12px;background:var(--vp-c-bg-soft);margin:18px 0 28px}.class-work-card label{font-weight:700;display:block;margin-bottom:6px}.class-work-card select{width:100%;padding:10px;border:1px solid var(--vp-c-divider);border-radius:6px;background:var(--vp-c-bg);color:var(--vp-c-text-1);font:inherit}.class-work-card h3{margin:18px 0 14px}.class-work-card dl{display:grid;grid-template-columns:100px 1fr;gap:12px;margin:14px 0 20px}.class-work-card dt{font-weight:700}.class-work-card dd{margin:0}.class-work-card ul{margin:8px 0 14px}.class-work-note{border-left:3px solid var(--vp-c-brand-1);padding-left:12px}.class-work-card small{display:block;line-height:1.5}.status{font-size:.76rem;border:1px solid var(--vp-c-divider);padding:2px 6px;border-radius:4px;font-weight:700}.class-work-card :focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@media(max-width:520px){.class-work-card{padding:16px}.class-work-card dl{grid-template-columns:1fr;gap:3px}.class-work-card dd{margin-bottom:10px}}</style>
